for R in [P,S]:
 recs=json.loads((R/'read-only-fields-inventory.json').read_text());cache={}
 for x in recs:
  raw=R/x['raw_RST'];rr=cache.setdefault(str(raw),reader.read_binary(str(raw)));i=x['set']-1;n,u=rr.nodal_solution(i);nn,ss=rr.nodal_stress(i);a=np.load(R/x['npz']);assert np.array_equal(n,nn);assert np.array_equal(a['source_node_ids'],n);assert np.array_equal(a['source_U'],u);assert np.array_equal(a['source_averaged_stress'],ss,equal_nan=True);assert np.array_equal(a['mesh_node_ids'],rr.mesh.nnum);assert np.array_equal(a['mesh_xyz'],rr.mesh.nodes);assert np.isfinite(u).all()
  mask=np.isfinite(ss).all(axis=1);xx,yy,zz,xy,yz,xz=ss.T;vm=np.sqrt(.5*((xx-yy)**2+(yy-zz)**2+(zz-xx)**2)+3*(xy**2+yz**2+xz**2));assert np.array_equal(mask,a['finite_stress_mask']);assert np.array_equal(vm,a['derived_averaged_VM'],equal_nan=True);assert len(n)==x['nodes'];assert float(np.linalg.norm(u[:,:3],axis=1).max())==x['max_U_source_units'];fieldchecks.append({'source':R.name,'case':x['case'],'set':x['set'],'exact_repeat_read':True,'finite_stress_nodes':int(mask.sum()),'missing_stress_nodes':int((~mask).sum())})
