for x in json.loads((P/'read-only-fields-inventory.json').read_text()):
 raw=P/x['raw_RST'];matches=[f for f in (P/'extracted-original').rglob('file.rst') if f.parent.parent.name==raw.parent.parent.name];assert len(matches)==1;assert matches[0].read_bytes()==raw.read_bytes();duplicates.append({'direct':x['raw_RST'],'archive_duplicate':str(matches[0].relative_to(P))})
